# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.errors import ProjectError
from rosterkit.models import Student

def _check_contacts(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )

def _cells(student: Student) -> List[str]:
    name = student.display_name
    return [name, student.section, student.email]

def _join(cells: List[str], widths: List[int]) -> str:
    pairs = zip(cells, widths)
    fitted = [cell.ljust(size) for cell, size in pairs]
    return "  ".join(fitted).rstrip()

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Aligned name, section, email rows sorted by name."""
    ordered = sorted(students, key=_sort_name)
    _check_contacts(ordered)
    table = [_cells(student) for student in ordered]
    widths = [max(map(len, part)) for part in zip(*table)]
    return [_join(cells, widths) for cells in table]

def _sort_name(student: Student) -> str:
    return student.display_name.lower()
